 resize(builder,{},{12,12,4},2);q=builderRequest(heavyRt,builder,all,es,false,&cancel,&progress);q.layer=0;q.iterations=100;auto fut=std::async(std::launch::async,[&]{return solve(q);});std::this_thread::sleep_for(std::chrono::milliseconds(10));auto stop=std::chrono::steady_clock::now();cancel=true;auto cancelledResult=fut.get();check(!cancelledResult.iterationsUsed&&cancelledResult.failStage=="cancelled","active worker acknowledges cancellation");check(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-stop).count()<100,"cancellation under 100ms");

